//     := []. The !closed branch calls SafeBoostedConstrainedStep whose postcondition
//     guarantees the returned next is EOS or parser-valid; AppendConstrainedToken
//     preserves parser.IsValidPrefix(currentConstrainedOut). EOS breaks without
//     modifying state.
//   Phases 3/6/7-close/8 (CloseSpanWithinBudget): postcondition directly guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//   Phase 4 (UnconstrainedStep): insideConstrainedOut is false on entry (loop guard);
//     we flip to true only via EnterObservedConstrainedSpan (sets currentConstrainedOut := []).
//   Phase 7 prefix (OpenConstrainedSpan): sets currentConstrainedOut := [] which is valid.
//
// progress (|generated| <= |generatedPrefix| + steps):
//   Phase 1: UnconstrainedChunk postcondition gives |cg| <= |generated| + stepsUsed;
//     we add exactly stepsUsed to steps.
//   Phase 2/5/7-inner: each iteration increments steps by exactly 1 (all branches).
//     Closed branch: CloseSpanIfComplete appends ">>" so |cg| = |generated| + 1; steps +1.
//     Non-closed branch: SafeBoostedConstrainedStep does not append; AppendConstrainedToken
//     appends at most 1 token; steps +1. EOS break leaves generated unchanged.
//     |currentConstrainedOut| check is a pure read that adds 0 to generated and 0 to steps.
//   Phases 3/6/7-close/8 (CloseSpanWithinBudget with budget B): postcondition gives
//     |generatedOut| <= |generated| + B; we add exactly B to steps.
//   Phase 4: UnconstrainedStep: steps +1, generated grows by at most 1 token.
//   Phase 7 OpenConstrainedSpan: steps +1, generated grows by exactly 1 ("<<").
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve step by step using symbolic variable names from the problem. The final line must be: The answer is <<EXPR>> where EXPR is a complete arithmetic expression using the exact placeholder variable names from the problem, numbers, and operators +, -, *, /, (, ), int(). Do not reduce to a bare number. Example: The answer is <<n * price - discount + tax>>. No LaTeX, no {}, no **, no $.";
helpers.AppendTaskGuidance(lm, guidance);

var flatGroups := CSDHelpers.FlattenTokenGroups(validTokenGroups);

var steps: nat := 0;
var hasCompletedSpan: bool := false;
var chunkSize: nat := 40;
var minInnerTokens: nat := 5;
var innerStepLimit: nat := 60;

var phase1Limit: nat := (maxSteps * 75) / 100;
if phase1Limit == 0 && maxSteps > 0 {
  phase1Limit := 1;
}

// Phase 1: Unconstrained chunks watching for "<<" opening delimiter
while steps < phase1Limit && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase1Limit - steps
{
  var actualChunk := chunkSize;
  if steps + actualChunk > phase1Limit {
    actualChunk := phase1Limit - steps;
  }
  if actualChunk == 0 {
    break;
  }
  var cg, stoppedOnOpen, stoppedOnEos, stepsUsed := helpers.UnconstrainedChunk(lm, prompt, generated, actualChunk, "<<", eosToken);
  generated := cg;
  steps := steps + stepsUsed;
  if stoppedOnEos {
    break;
  }
  if stoppedOnOpen {
    var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg;
    insideConstrainedOut := ei;
    currentConstrainedOut := ec;
  }
}

// Phase 2: Constrained generation with delayed close (minInnerTokens guard)
var innerSteps: nat := 0;

while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && innerSteps < innerStepLimit
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + innerStepLimit - innerSteps
{
  if |currentConstrainedOut| >= minInnerTokens {
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
      hasCompletedSpan := true;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeBoostedConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, flatGroups, 2.0, eosToken);
      steps := steps + 1;
      innerSteps := innerSteps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.SafeBoostedConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, flatGroups, 2.0, eosToken);
    steps := steps + 1;
    innerSteps := innerSteps + 1;
    if next == eosToken {
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 3: CloseSpanWithinBudget if still open after inner loop
if insideConstrainedOut && steps < maxSteps {
  var spanBudget: nat := 30;
  var remaining := maxSteps - steps;
  if spanBudget > remaining {
    spanBudget := remaining;
  }
  if spanBudget > 0 {
    var wg, wi, wc := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, spanBudget);
    generated := wg;
    insideConstrainedOut := wi;
    currentConstrainedOut := wc;
    steps := steps + spanBudget;
    if !insideConstrainedOut {
      hasCompletedSpan := true;
    }
  }
}

// Phase 4: More free generation if no span seen yet (RenderedEndsWith for "<<")
while steps < phase1Limit && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase1Limit - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
  if RenderedEndsWith(generated, "<<") {
    var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg;
    insideConstrainedOut := ei;
    currentConstrainedOut := ec;
  }
}

// Phase 5: Second constrained loop with same minInnerTokens guard
var innerSteps2: nat := 0;

while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && innerSteps2 < innerStepLimit
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + innerStepLimit - innerSteps2
{
  if |currentConstrainedOut| >= minInnerTokens {
    var cg2, ci2, cc2, closed2 := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    if closed2 {
      generated := cg2;
      insideConstrainedOut := ci2;
      currentConstrainedOut := cc2;
      steps := steps + 1;
      hasCompletedSpan := true;
    } else {
      var constrainedPrompt2 := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next2 := helpers.SafeBoostedConstrainedStep(lm, parser, constrainedPrompt2, currentConstrainedOut, flatGroups, 2.0, eosToken);
      steps := steps + 1;
      innerSteps2 := innerSteps2 + 1;
      if next2 == eosToken {
        break;
      } else {
        var ag2, ai2, ac2 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next2);
        generated := ag2;
        insideConstrainedOut := ai2;
        currentConstrainedOut := ac2;
      }
    }
  } else {
    var constrainedPrompt2 := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next2 := helpers.SafeBoostedConstrainedStep(lm, parser, constrainedPrompt2, currentConstrainedOut, flatGroups, 2.0, eosToken);
    steps := steps + 1;
    innerSteps2 := innerSteps2 + 1;
    if next2 == eosToken {
      break;
    } else {
      var ag2, ai2, ac2 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next2);
      generated := ag2;
      insideConstrainedOut := ai2;
      currentConstrainedOut := ac2;
    }
  }
}

// Phase 6: CloseSpanWithinBudget if still open
if insideConstrainedOut && steps < maxSteps {
  var spanBudget2: nat := 30;
  var remaining2 := maxSteps - steps;
  if spanBudget2 > remaining2 {
    spanBudget2 := remaining2;
  }
  if spanBudget2 > 0 {
    var wg2, wi2, wc2 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, spanBudget2);
    generated := wg2;
    insideConstrainedOut := wi2;
    currentConstrainedOut := wc2;
    steps := steps + spanBudget2;
    if !insideConstrainedOut {
      hasCompletedSpan := true;
    }
  }
}

// Phase 7: Force open a span if none completed yet
if !insideConstrainedOut && !hasCompletedSpan && steps < maxSteps {
  if steps + 2 <= maxSteps {
    var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
    generated := fg;
    insideConstrainedOut := fi;
    currentConstrainedOut := fc;
    steps := steps + 1;

    var innerSteps3: nat := 0;
    var innerLimit3: nat := 40;

    while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && innerSteps3 < innerLimit3
      invariant 0 <= steps <= maxSteps
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut ==> currentConstrainedOut == []
      invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
      invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
      invariant |generated| <= |generatedPrefix| + steps
      decreases maxSteps - steps + innerLimit3 - innerSteps3
    {
      if |currentConstrainedOut| >= minInnerTokens {
        var cg3, ci3, cc3, closed3 := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
        if closed3 {
          generated := cg3;
          insideConstrainedOut := ci3;
          currentConstrainedOut := cc3;
          steps := steps + 1;
          hasCompletedSpan := true;
        } else {
          var constrainedPrompt3 := prompt + generated[..|generated| - |currentConstrainedOut|];
          var next3 := helpers.SafeBoostedConstrainedStep(lm, parser, constrainedPrompt3, currentConstrainedOut, flatGroups, 2.0, eosToken);
          steps := steps + 1;
          innerSteps3 := innerSteps3 + 1;
          if next3 == eosToken {
            break;
          } else {
            var ag3, ai3, ac3 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next3);
            generated := ag3;
            insideConstrainedOut := ai3;
            currentConstrainedOut := ac3;
          }
        }
      } else {
        var constrainedPrompt3 := prompt + generated[..|generated| - |currentConstrainedOut|];
        var next3 := helpers.SafeBoostedConstrainedStep(lm, parser, constrainedPrompt3, currentConstrainedOut, flatGroups, 2.0, eosToken);
        steps := steps + 1;
        innerSteps3 := innerSteps3 + 1;
        if next3 == eosToken {
          break;
        } else {
          var ag3, ai3, ac3 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next3);
          generated := ag3;
          insideConstrainedOut := ai3;
          currentConstrainedOut := ac3;
        }
      }
    }

    if insideConstrainedOut && steps < maxSteps {
      var remainBudget := maxSteps - steps;
      if remainBudget > 30 {
        remainBudget := 30;
      }
      if remainBudget > 0 {
        var wg3, wi3, wc3 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainBudget);
        generated := wg3;
        insideConstrainedOut := wi3;
        currentConstrainedOut := wc3;
        steps := steps + remainBudget;
      }
    }
  }
}

// Phase 8: Final safety CloseSpanWithinBudget
if insideConstrainedOut && steps < maxSteps {
  var finalBudget := maxSteps - steps;
  if finalBudget > 0 {
    var wg4, wi4, wc4 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, finalBudget);
    generated := wg4;
    insideConstrainedOut := wi4;
    currentConstrainedOut := wc4;
    steps := steps + finalBudget;
  }
}

cost := steps;
